1	//! The compiler for the _Typst_ markup language.
2	//!
3	//! # Steps
4	//! - **Parsing:**
5	//!   The compiler first transforms a plain string into an iterator of [tokens].
6	//!   This token stream is [parsed] into a [syntax tree]. The tree itself is
7	//!   untyped, but the [AST] module provides a typed layer over it.
8	//! - **Evaluation:**
9	//!   The next step is to [evaluate] the markup. This produces a [module],
10	//!   consisting of a scope of values that were exported by the code and
11	//!   [content], a hierarchical, styled representation of what was written in
12	//!   the source file. The elements of the content tree are well structured and
13	//!   order-independent and thus much better suited for further processing than
14	//!   the raw markup.
15	//! - **Layouting:**
16	//!   Next, the content is [laid out] into a
17	//!   [`PagedDocument`](typst_layout::PagedDocument) containing one [frame] per
18	//!   page with items at fixed positions.
19	//! - **Exporting:**
20	//!   These frames can finally be exported into an output format (currently PDF,
21	//!   PNG, SVG, and HTML).
22	//!
23	//! [tokens]: typst_syntax::SyntaxKind
24	//! [parsed]: typst_syntax::parse
25	//! [syntax tree]: typst_syntax::SyntaxNode
26	//! [AST]: typst_syntax::ast
27	//! [evaluate]: typst_eval::eval
28	//! [module]: crate::foundations::Module
29	//! [content]: crate::foundations::Content
30	//! [laid out]: typst_layout::layout_document
31	//! [frame]: crate::layout::Frame
32	
33	pub extern crate comemo;
34	pub extern crate ecow;
35	
36	pub use typst_library::*;
37	#[doc(inline)]
38	pub use typst_syntax as syntax;
39	#[doc(inline)]
40	pub use typst_utils as utils;
41	
42	use std::sync::LazyLock;
43	
44	use arrayvec::ArrayVec;
45	use comemo::{Track, Tracked};
46	use ecow::{EcoString, EcoVec, eco_format, eco_vec};
47	use rustc_hash::FxHashSet;
48	use typst_library::diag::{
49	    FileError, SourceDiagnostic, SourceResult, Warned, bail, warning,
50	};
51	use typst_library::engine::{Engine, Route, Sink, Traced};
52	use typst_library::format::Format;
53	use typst_library::foundations::{
54	    NativeRuleMap, Output, StyleChain, Styles, Target, TargetElem, Value,
55	};
56	use typst_library::introspection::{
57	    EmptyIntrospector, ITER_NAMES, Introspector, MAX_ITERS,
58	};
59	use typst_library::routines::Routines;
60	use typst_syntax::{FileId, Span};
61	use typst_timing::{TimingScope, timed};
62	use typst_utils::Protected;
63	
64	/// Compiles sources into an output.
65	///
66	/// Supported outputs are
67	/// - the `PagedDocument` (defined in `typst_layout`)
68	/// - the `HtmlDocument` (defined in `typst_html`)
69	///
70	/// Returns the compilation output alongside warnings, if any. The contained
71	/// result is
72	/// - `Ok(output)` if there were no fatal errors.
73	/// - `Err(errors)` if there were fatal errors.
74	#[typst_macros::time]
75	pub fn compile<T>(world: &dyn World) -> Warned<SourceResult<T>>
76	where
77	    T: Output,
78	{
79	    let mut sink = Sink::new();
80	    let output = compile_impl::<T>(world.track(), Traced::default().track(), &mut sink)
81	        .map_err(deduplicate);
82	    Warned { output, warnings: sink.warnings() }
83	}
84	
85	/// Compiles sources and returns all values and styles observed at the given
86	/// `span` during compilation.
87	#[typst_macros::time]
88	pub fn trace<T>(world: &dyn World, span: Span) -> EcoVec<(Value, Option<Styles>)>
89	where
90	    T: Output,
91	{
92	    let mut sink = Sink::new();
93	    let traced = Traced::new(span);
94	    compile_impl::<T>(world.track(), traced.track(), &mut sink).ok();
95	    sink.values()
96	}
97	
98	/// The internal implementation of `compile` with a bit lower-level interface
99	/// that is also used by `trace`.
100	fn compile_impl<T: Output>(
101	    world: Tracked<dyn World + '_>,
102	    traced: Tracked<Traced>,
103	    sink: &mut Sink,
104	) -> SourceResult<T> {
105	    let library = world.library();
106	    match T::target() {
107	        Target::Paged => {}
108	        Target::Html => warn_or_error_for_html(&library.features, sink)?,
109	        Target::Bundle => warn_or_error_for_bundle(&library.features, sink)?,
110	    }
111	
112	    let base = StyleChain::new(&library.styles);
113	    let target = TargetElem::target.set(T::target()).wrap();
114	    let styles = base.chain(&target);
115	    let empty_introspector = EmptyIntrospector;
116	
117	    // Fetch the main source file once.
118	    let main = world.main();
119	    let main = world
120	        .source(main)
121	        .map_err(|err| hint_invalid_main_file(world, err, main))?;
122	
123	    // First evaluate the main source file into a module.
124	    let content = typst_eval::eval(
125	        world,
126	        library,
127	        traced,
128	        sink.track_mut(),
129	        Route::default().track(),
130	        &main,
131	    )?
132	    .content();
133	
134	    let mut history: ArrayVec<T, { MAX_ITERS - 1 }> = ArrayVec::new();
135	    let mut document: T;
136	
137	    // Relayout until all introspections stabilize.
138	    // If that doesn't happen within five attempts, we give up.
139	    loop {
140	        let _scope = TimingScope::new(ITER_NAMES[history.len()]);
141	        let introspector = history
142	            .last()
143	            .map(|doc| doc.introspector())
144	            .unwrap_or(&empty_introspector);
145	        let constraint = comemo::Constraint::new();
146	
147	        let mut subsink = Sink::new();
148	        let mut engine = Engine {
149	            library,
150	            world,
151	            introspector: Protected::new(introspector.track_with(&constraint)),
152	            traced,
153	            sink: subsink.track_mut(),
154	            route: Route::default(),
155	        };
156	
157	        document = T::create(&mut engine, &content, styles)?;
158	
159	        if timed!("check stabilized", constraint.validate(document.introspector())) {
160	            sink.extend_from_sink(subsink);
161	            break;
162	        }
163	
164	        if history.is_full() {
165	            let mut introspectors =
166	                [&empty_introspector as &dyn Introspector; MAX_ITERS + 1];
167	            for i in 1..MAX_ITERS {
168	                introspectors[i] = history[i - 1].introspector();
169	            }
170	            introspectors[MAX_ITERS] = document.introspector();
171	
172	            let warnings = typst_library::introspection::analyze(
173	                world,
174	                introspectors,
175	                subsink.introspections(),
176	            );
177	
178	            sink.extend_from_sink(subsink);
179	            for warning in warnings {
180	                sink.warn(warning);
181	            }
182	            break;
183	        }
184	
185	        history.push(document);
186	    }
187	
188	    // Promote delayed errors.
189	    let delayed = sink.delayed();
190	    if !delayed.is_empty() {
191	        return Err(delayed);
192	    }
193	
194	    Ok(document)
195	}
196	
197	/// Deduplicate diagnostics.
198	fn deduplicate(mut diags: EcoVec<SourceDiagnostic>) -> EcoVec<SourceDiagnostic> {
199	    let mut unique = FxHashSet::default();
200	    diags.retain(|diag| {
201	        let hash = typst_utils::hash128(&(&diag.span, &diag.message));
202	        unique.insert(hash)
203	    });
204	    diags
205	}
206	
207	/// Adds useful hints when the main source file couldn't be read
208	/// and returns the final diagnostic.
209	fn hint_invalid_main_file(
210	    world: Tracked<dyn World + '_>,
211	    file_error: FileError,
212	    input: FileId,
213	) -> EcoVec<SourceDiagnostic> {
214	    let is_utf8_error = matches!(file_error, FileError::InvalidUtf8);
215	    let mut diagnostic =
216	        SourceDiagnostic::error(Span::detached(), EcoString::from(file_error));
217	
218	    // Attempt to provide helpful hints for UTF-8 errors. Perhaps the user
219	    // mistyped the filename. For example, they could have written "file.pdf"
220	    // instead of "file.typ".
221	    if is_utf8_error {
222	        match input.vpath().extension() {
223	            // No hints if the file is already a .typ file. The file is indeed
224	            // just invalid.
225	            Some("typ") => return eco_vec![diagnostic],
226	
227	            Some(ext) => {
228	                diagnostic.hint(eco_format!(
229	                    "a file with the `.{ext}` extension is not usually a Typst file",
230	                ));
231	            }
232	
233	            None => {
234	                diagnostic
235	                    .hint("a file without an extension is not usually a Typst file");
236	            }
237	        }
238	
239	        if world.source(input.map(|p| p.with_extension("typ")).intern()).is_ok() {
240	            diagnostic.hint("check if you meant to use the `.typ` extension instead");
241	        }
242	    }
243	
244	    eco_vec![diagnostic]
245	}
246	
247	/// HTML export will warn or error depending on whether the feature flag is enabled.
248	fn warn_or_error_for_html(features: &Features, sink: &mut Sink) -> SourceResult<()> {
249	    const ISSUE: &str = "https://github.com/typst/typst/issues/5512";
250	    if features.is_enabled(Feature::Html) {
251	        sink.warn(warning!(
252	            Span::detached(),
253	            "html export is under active development and incomplete";
254	            hint: "its behaviour may change at any time";
255	            hint: "do not rely on this feature for production use cases";
256	            hint: "see {ISSUE} for more information";
257	        ));
258	    } else {
259	        bail!(
260	            Span::detached(),
261	            "html export is only available when `--features html` is passed";
262	            hint: "html export is under active development and incomplete";
263	            hint: "see {ISSUE} for more information";
264	        );
265	    }
266	    Ok(())
267	}
268	
269	/// Bundle export will warn or error depending on whether the feature flag is
270	/// enabled.
271	fn warn_or_error_for_bundle(features: &Features, sink: &mut Sink) -> SourceResult<()> {
272	    if features.is_enabled(Feature::Bundle) {
273	        sink.warn(warning!(
274	            Span::detached(),
275	            "bundle export is experimental";
276	            hint: "its behaviour may change at any time";
277	            hint: "do not rely on this feature for production use cases";
278	        ));
279	    } else {
280	        bail!(
281	            Span::detached(),
282	            "bundle export is only available when `--features bundle` is passed";
283	            hint: "bundle export is experimental";
284	        );
285	    }
286	    Ok(())
287	}
288	
289	/// Provides ways to construct a [`Library`].
290	pub trait LibraryExt {
291	    /// Creates the default library.
292	    ///
293	    /// Requires passing in all formats that should be registered, see
294	    /// [`Self::builder()`]
295	    #[expect(clippy::new_ret_no_self)]
296	    fn new(formats: impl IntoIterator<Item = Format>) -> Library;
297	
298	    /// Creates a builder for configuring a library.
299	    ///
300	    /// Requires passing in all formats that should be registered.
301	    /// ```
302	    /// use typst::{Library, LibraryExt};
303	    ///
304	    /// Library::builder([
305	    ///     typst_html::FORMAT,
306	    ///     typst_pdf::FORMAT,
307	    ///     typst_svg::FORMAT,
308	    ///     typst_render::FORMAT,
309	    ///     typst_bundle::FORMAT,
310	    /// ]);
311	    /// ```
312	    fn builder(formats: impl IntoIterator<Item = Format>) -> LibraryBuilder;
313	}
314	
315	impl LibraryExt for Library {
316	    fn new(formats: impl IntoIterator<Item = Format>) -> Library {
317	        Self::builder(formats).build()
318	    }
319	
320	    fn builder(formats: impl IntoIterator<Item = Format>) -> LibraryBuilder {
321	        LibraryBuilder::from_routines(&ROUTINES, formats)
322	    }
323	}
324	
325	/// Defines implementation of various Typst compiler routines as a table of
326	/// function pointers.
327	///
328	/// This is essentially dynamic linking and done to allow for crate splitting.
329	static ROUTINES: LazyLock<Routines> = LazyLock::new(|| Routines {
330	    rules: || {
331	        let mut rules = NativeRuleMap::new();
332	        typst_layout::register(&mut rules);
333	        typst_html::register(&mut rules);
334	        rules
335	    },
336	    eval_string: typst_eval::eval_string,
337	    eval_closure: typst_eval::eval_closure,
338	    realize: typst_realize::realize,
339	    layout_frame: typst_layout::layout_frame,
340	    html_mathml_body: typst_html::html_mathml_body,
341	    html_span_filled: typst_html::html_span_filled,
342	});
343	
344	#[cfg(test)]
345	mod tests {
346	    use super::*;
347	
348	    #[test]
349	    fn formats() {
350	        // No formats at all.
351	        Library::new([]);
352	        // Only the HTML format.
353	        Library::new([typst_html::FORMAT]);
354	        // Only a paged format.
355	        Library::new([typst_svg::FORMAT]);
356	    }
357	}
